B.as1=s(["\u5c07\u9810\u4ed8\u652f\u51fa\u8ffd\u8e64\u6574\u5408\u9032\u8a18\u5e33\u6e05\u55ae\uff0c\u672a\u7e73\u6e05\u7684\u8de8\u6708\u9805\u76ee\u4e5f\u6703\u986f\u793a\uff0c\u9032\u5ea6\u3001\u7e73\u6b3e\u8207\u5176\u4ed6\u8a73\u7d30\u8cc7\u6599\u6539\u70ba\u5c55\u958b\u5f8c\u67e5\u770b\u3002","PC \u7248\u8a18\u5e33\u7ba1\u7406\u3001\u884c\u7a0b\u898f\u5283\u8207\u5de5\u4f5c\u8ffd\u8e64\u5c07\u4e3b\u8981\u7d71\u8a08\u5361\u6574\u5408\u81f3\u4e0a\u65b9\u8cc7\u8a0a\u5340\uff0c\u79fb\u9664\u4e0b\u65b9\u91cd\u8907\u5361\u7247\u4e26\u7e2e\u77ed\u95b1\u8b80\u52d5\u7dda\u3002","\u6708\u66c6\u7e3d\u89bd\u65b0\u589e\u6700\u8fd1\u7684\u4e0b\u4e00\u5834\u8cc7\u8a0a\uff0c\u4e26\u6bcf\u5206\u9418\u81ea\u52d5\u5224\u65b7\u8207\u63a5\u7e8c\u4e0b\u4e00\u7b46\u5c1a\u672a\u7d50\u675f\u7684\u884c\u7a0b\u3002"],t.s)
B.ayW=s(["Merged advance-expense tracking into the ledger list, including outstanding items from earlier months, with payment progress and details available on expansion.","Moved the primary statistics for ledger, schedule, and work tracking into compact desktop banners and removed duplicate lower cards.","Added the next upcoming schedule to the dashboard with automatic minute-by-minute advancement across months."],t.s)
B.Xe=new A.cv("v1.2.84+92","\u6574\u5408\u9810\u4ed8\u8ffd\u8e64\u8207\u6fc3\u7e2e\u9801\u9762\u8cc7\u8a0a","Unified advance tracking and compact desktop summaries",B.as1,B.ayW)
